import re
import sys
from datetime import datetime

PATH = sys.argv[1] if len(sys.argv) > 1 else "kickoff.ics"

with open(PATH, "rb") as f:
    raw = f.read()

# Normalize to RFC 5545 CRLF line endings
text = raw.decode("utf-8").replace("\r\n", "\n").replace("\r", "\n")
normalized = text.replace("\n", "\r\n")
with open(PATH, "wb") as f:
    f.write(normalized.encode("utf-8"))

lines = [ln.strip() for ln in normalized.split("\r\n")]

errors = []
if lines[0] != "BEGIN:VCALENDAR":
    errors.append("file must start with BEGIN:VCALENDAR")
if lines[-1] != "END:VCALENDAR":
    errors.append("file must end with END:VCALENDAR")
if "VERSION:2.0" not in lines:
    errors.append("missing VERSION:2.0")
if not any(ln.startswith("PRODID:") for ln in lines):
    errors.append("missing PRODID")
if "BEGIN:VEVENT" not in lines or "END:VEVENT" not in lines:
    errors.append("missing VEVENT block")
if not any(ln.startswith("UID:") for ln in lines):
    errors.append("missing UID")
if not any(ln.startswith("DTSTAMP:") for ln in lines):
    errors.append("missing DTSTAMP")

def parse_dt(v):
    return datetime.strptime(v, "%Y%m%dT%H%M%SZ")

dtstart = dtend = None
for ln in lines:
    if ln.startswith("DTSTART:"):
        dtstart = parse_dt(ln.split(":", 1)[1])
    if ln.startswith("DTEND:"):
        dtend = parse_dt(ln.split(":", 1)[1])

if dtstart is None:
    errors.append("missing DTSTART")
if dtend is None:
    errors.append("missing DTEND")
if dtstart and dtend:
    if dtend <= dtstart:
        errors.append("DTEND must be after DTSTART")
    hours = (dtend - dtstart).total_seconds() / 3600
    if hours != 2.0:
        errors.append(f"expected 2-hour duration, got {hours}h")

summary = next((ln.split(":", 1)[1] for ln in lines if ln.startswith("SUMMARY:")), None)
if not summary:
    errors.append("missing SUMMARY")
if "BEGIN:VALARM" not in lines or "END:VALARM" not in lines:
    errors.append("missing VALARM reminder")
if "TRIGGER:-PT15M" not in lines:
    errors.append("expected 15-minute reminder trigger")

print("=== kickoff.ics validation ===")
print(f"Line endings : CRLF (RFC 5545)")
print(f"Summary      : {summary}")
print(f"DTSTART (UTC): {dtstart.isoformat() if dtstart else 'MISSING'}")
print(f"DTEND   (UTC): {dtend.isoformat() if dtend else 'MISSING'}")
print(f"Duration     : {(dtend - dtstart).total_seconds() / 3600:.0f} hours" if dtstart and dtend else "Duration     : N/A")
print(f"Reminder     : 15 minutes before (TRIGGER:-PT15M)")
if errors:
    print("Result       : INVALID")
    for e in errors:
        print(f"  - {e}")
    sys.exit(1)
print("Result       : VALID")

